export const programOwnerQaId=n=>'10000000-0000-4000-8000-'+String(n).padStart(12,'0');
export const programOwnerQaItems=()=>salaryItems([
 {kind:'concept',code:'1',agreementCode:'1',categoryCode:null,label:'Básico exclusivamente sintético',nature:'remuneration',unit:'money',precision:2,value:null,validFrom:'2026-10',validUntil:'2026-10',active:true,ruleReference:'Documento ficticio QA190',dependencies:[]},
 {kind:'auxiliary',code:'101',agreementCode:'1',categoryCode:null,label:'Mes exclusivamente sintético',nature:'auxiliary',unit:'units',precision:0,value:null,validFrom:'2026-10',validUntil:'2026-10',active:true,ruleReference:'Documento ficticio QA190',dependencies:[]}
]);
export function programOwnerQaDefinition(){return ownProgramDefinition({namespaceVersion:'own-payroll-namespaces.v2',periodContextVersion:'own-payroll-period-context.v1',totalsPrecision:2,rules:[
 {code:'1',agreementCode:'1',nature:'remuneration',unit:'money',validFrom:'2026-10',validUntil:'2026-10',liquidationTypes:['monthly'],ruleReference:'Regla inventada QA190, sin norma municipal',rounding:{mode:'exact',precision:2},expression:{op:'literal',value:'100.10',unit:'money'}},
 {code:'101',agreementCode:'1',nature:'auxiliary',unit:'units',validFrom:'2026-10',validUntil:'2026-10',liquidationTypes:['monthly'],ruleReference:'Mes declarado ficticio QA190',rounding:{mode:'exact',precision:0},expression:{op:'input',key:'month',unit:'units'}}
],bindings:[{agreementCode:'1',key:'month',unit:'units',sourceKind:'period_context_fact',sourceField:'monthNumber',onMissing:'error',combine:'single',ruleReference:'Fuente propia declarada ficticia QA190'}]},programOwnerQaItems());}
export function programOwnerQaAuthority(){return{version:'municipal-owner-program-authority.v1',scope:{tenantId:programOwnerQaId(1),membershipId:programOwnerQaId(2),bindingId:programOwnerQaId(3),companyId:101},authority:{version:'municipal-adoption-owner-authority.v1',policyVersion:'tenant-owner-adoption-policy.v1',policySha256:'3cd05ec553d4e19e511b4d755224efe36a470a02502704a621dec608ad312305',actor:{personId:programOwnerQaId(4),email:'owner-program@example.invalid',identityVersion:2,sessionId:programOwnerQaId(5),sessionVersion:3,releaseSha:'a'.repeat(40)}},policy:{version:OWNER_PROGRAM_POLICY.version,sha256:OWNER_PROGRAM_POLICY_SHA256},scopeVersion:'b'.repeat(64)};}
export async function programOwnerQaPreview(){const definition=programOwnerQaDefinition(),baseDefinition=ownProgramStructure({...definition,rules:definition.rules.filter(r=>r.nature!=='auxiliary'),bindings:[]}),items=programOwnerQaItems(),value={version:'municipal-owner-program-preview.v1',decisionMode:'owner',independence:false,context:programOwnerQaAuthority(),proposal:{id:programOwnerQaId(6),requestSha256:'c'.repeat(64),baseVersion:'d'.repeat(64),salaryVersion:'f'.repeat(64),baseDefinition,definition,salaryItems:items,reason:'Preparación sintética completa',authorLabel:'Responsable sintético',createdAt:'2026-10-15T12:00:00+00:00'},definitionSha256:await adoptionReviewHash(definition),salaryItemsSha256:await adoptionReviewHash(items),classificationVersion:'9'.repeat(64),current:true};return{...value,previewSha256:await adoptionReviewHash(value)};}
export async function programOwnerQaReceipt(command,key,{preview=undefined,replayed=false}={}){return{version:'municipal-owner-program-receipt.v1',decisionMode:'owner',independence:false,eventId:programOwnerQaId(80),proposalId:command.proposalId,requestKey:key,requestSha256:await adoptionReviewHash({operation:'approve_owner',body:command}),canonicalRequestSha256:await adoptionReviewHash(ownerProgramNativeCommand(command)),programVersion:'e'.repeat(64),revision:1,rulesTotal:preview?.proposal.definition.rules.length??2,bindingsTotal:preview?.proposal.definition.bindings.length??1,previewSha256:command.previewSha256,definitionSha256:command.definitionSha256,salaryItemsSha256:command.salaryItemsSha256,policySha256:OWNER_PROGRAM_POLICY_SHA256,replayed};}
